245 | # ─── GDPR / PII Detection ─────────────────────────────────────────────────────
246 | 
247 | # Column name patterns that suggest PII/sensitive data (case-insensitive).
248 | # Uses (?<![a-z0-9]) / (?![a-z0-9]) as word boundaries so that underscore-
249 | # delimited names like "patient_name" or "first_name" are also matched.
250 | _PII_COLUMN_PATTERNS = [
251 |     r"(?<![a-z0-9])name(?![a-z0-9])",
252 |     r"first.?name", r"last.?name", r"full.?name", r"sur.?name",
253 |     r"(?<![a-z0-9])ssn(?![a-z0-9])", r"social.?security", r"ssin",
254 |     r"passport", r"national.?id", r"personal.?id",
255 |     r"(?<![a-z0-9])nid(?![a-z0-9])",
256 |     r"(?<![a-z0-9])dob(?![a-z0-9])", r"date.?of.?birth", r"birth.?date",
257 |     r"(?<![a-z0-9])email(?![a-z0-9])", r"e.?mail",
258 |     r"(?<![a-z0-9])phone(?![a-z0-9])", r"mobile", r"telephone",
259 |     r"address", r"(?<![a-z0-9])street(?![a-z0-9])",
260 |     r"(?<![a-z0-9])zip(?![a-z0-9])", r"postcode", r"postal",
261 |     r"ip.?address",
262 |     r"patient.?id", r"subject.?id", r"participant.?id",
263 |     r"medical.?record", r"(?<![a-z0-9])mrn(?![a-z0-9])",
264 |     r"(?<![a-z0-9])gender(?![a-z0-9])", r"(?<![a-z0-9])sex(?![a-z0-9])",
265 |     r"(?<![a-z0-9])race(?![a-z0-9])", r"ethnicity",
266 |     r"diagnosis", r"(?<![a-z0-9])condition(?![a-z0-9])",
267 |     r"birthday", r"(?<![a-z0-9])age(?![a-z0-9])",
268 |     r"(?<![a-z0-9])salary(?![a-z0-9])", r"income", r"financial",
269 |     r"biometric", r"fingerprint",
270 | ]
271 | 
272 | # Cell-level regex patterns for common PII formats
273 | _PII_CELL_PATTERNS = {
274 |     "SSN":          re.compile(r"\b\d{3}-\d{2}-\d{4}\b"),
275 |     "Email":        re.compile(r"\b[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}\b"),
276 |     "Phone (US)":   re.compile(r"\b(?:\+?1[\s\-.]?)?\(?\d{3}\)?[\s\-.]?\d{3}[\s\-.]?\d{4}\b"),
277 |     "Date of Birth":re.compile(r"\b(?:19|20)\d{2}[\/\-]\d{2}[\/\-]\d{2}\b"),
278 |     "Passport/ID":  re.compile(r"\b[A-Z]{1,2}\d{6,9}\b"),
279 |     "Postcode (UK)":re.compile(r"\b[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}\b"),
280 |     "IP Address":   re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b"),
281 | }
282 | 
283 | def scan_pii(df: pd.DataFrame) -> dict:
284 |     """
285 |     Scan a DataFrame for potential PII.
286 | 
287 |     Returns a dict:
288 |         {
289 |           "flagged_columns": [list of column names matching PII patterns],
290 |           "cell_findings":   {column: {pii_type: count, ...}, ...},
291 |           "has_pii": bool,
292 |         }
293 |     """
294 |     flagged_columns = []
295 |     for col in df.columns:
296 |         col_lower = str(col).lower()
297 |         for pat in _PII_COLUMN_PATTERNS:
298 |             if re.search(pat, col_lower):
299 |                 flagged_columns.append(col)
300 |                 break
301 | 
302 |     cell_findings: dict = {}
303 |     # Scan string columns for PII patterns in a sample (up to 500 rows for speed)
304 |     sample = df.head(500)
305 |     for col in df.columns:
306 |         col_str = sample[col].astype(str)
307 |         col_hits: dict = {}
308 |         for pii_type, pattern in _PII_CELL_PATTERNS.items():
309 |             matches = col_str.str.count(pattern).sum()
310 |             if matches > 0:
311 |                 col_hits[pii_type] = int(matches)
312 |         if col_hits:
313 |             cell_findings[col] = col_hits
314 | 
315 |     has_pii = bool(flagged_columns or cell_findings)
316 |     return {
317 |         "flagged_columns": flagged_columns,
318 |         "cell_findings":   cell_findings,
319 |         "has_pii":         has_pii,
320 |     }
321 | 
