323 | def render_pii_warning(pii_result: dict) -> None:
324 |     """Render a GDPR/PII warning banner in the Streamlit UI."""
325 |     if not pii_result["has_pii"]:
326 |         return
327 | 
328 |     col_list = ", ".join(f"<code>{c}</code>" for c in pii_result["flagged_columns"]) or "—"
329 |     cell_parts = []
330 |     for col, hits in pii_result["cell_findings"].items():
331 |         for pii_type, count in hits.items():
332 |             cell_parts.append(f"<code>{col}</code>: {count}× {pii_type}")
333 |     cell_detail = "; ".join(cell_parts) if cell_parts else "—"
334 | 
335 |     st.markdown(f"""
336 |     <div class="pii-warning">
337 |       <strong>⚠ GDPR / Sensitive Data Alert</strong><br>
338 |       The uploaded dataset may contain <strong>personally identifiable information (PII)</strong>
339 |       or sensitive data that is subject to GDPR, HIPAA, or equivalent data-protection regulations.<br><br>
340 |       <strong>Flagged column names:</strong> {col_list}<br>
341 |       <strong>Flagged cell patterns:</strong> {cell_detail}<br><br>
342 |       Please ensure you have a lawful basis for processing this data, that data subjects have been
343 |       informed, and that this system is operated in a GDPR-compliant environment.
344 |       Do <em>not</em> upload real personal data unless your organisation's data-processing agreement
345 |       covers this application.
346 |     </div>
347 |     """, unsafe_allow_html=True)
