350 | # ─── Data validation ───────────────────────────────────────────────────────────
351 | 
352 | REQUIRED_DATA_COLUMNS = {"Animal_ID", "Cohort", "Target_Dose_mg_kg", "Actual_Dose_mg_kg"}
353 | REQUIRED_RULES_COLUMNS = {"Assay_Parameter", "Minor_Variance_Limit_Percent", "Major_Variance_Limit_Percent"}
354 | 
355 | def validate_data_df(df: pd.DataFrame) -> list[str]:
356 |     """Return list of validation error strings; empty list = valid."""
357 |     errors = []
358 |     missing = REQUIRED_DATA_COLUMNS - set(df.columns)
359 |     if missing:
360 |         errors.append(f"Missing required columns: {', '.join(sorted(missing))}")
361 |     if len(df) == 0:
362 |         errors.append("The uploaded file contains no data rows.")
363 |     for col in ("Target_Dose_mg_kg", "Actual_Dose_mg_kg"):
364 |         if col in df.columns and not pd.api.types.is_numeric_dtype(df[col]):
365 |             errors.append(f"Column '{col}' must be numeric.")
366 |     return errors
367 | 
368 | def validate_rules_json(rules: dict) -> list[str]:
369 |     """Return list of validation error strings; empty list = valid."""
370 |     errors = []
371 |     if "rules" not in rules:
372 |         errors.append("Rules file must contain a top-level 'rules' key.")
373 |         return errors
374 |     if not isinstance(rules["rules"], list) or len(rules["rules"]) == 0:
375 |         errors.append("The 'rules' list is empty or not a list.")
376 |         return errors
377 |     for i, rule in enumerate(rules["rules"]):
378 |         missing = REQUIRED_RULES_COLUMNS - set(rule.keys())
379 |         if missing:
380 |             errors.append(f"Rule #{i+1} is missing fields: {', '.join(sorted(missing))}")
381 |     return errors
382 | 
383 | 
384 | # ─── Process data (vectorized — replaces iterrows loop) ───────────────────────
385 | 
386 | COHORT_RULE_MAP = {
387 |     "Group_1_Low":     "Body Weight Change",
388 |     "Group_2_Mid":     "Serum Glucose",
389 |     "Group_3_High":    "Heart Rate",
390 |     "Group_4_Control": "Alanine Aminotransferase (ALT)",
391 | }
392 | 
393 | @st.cache_data(show_spinner=False)
394 | def process_preclinical_data(df_hash: str, df: pd.DataFrame, rules_json: dict, project_id: str) -> pd.DataFrame:
395 |     """
396 |     Fully vectorized compliance processing. df_hash is a stable cache key
397 |     derived from the DataFrame content; it is not used inside the function.
398 |     """
399 |     rules_by_param = {r["Assay_Parameter"]: r for r in rules_json["rules"]}
400 |     fallback_rule   = min(rules_json["rules"], key=lambda r: r["Minor_Variance_Limit_Percent"])
401 | 
402 |     df = df.copy()
403 |     df["Deviation_Pct"] = (
404 |         (df["Actual_Dose_mg_kg"] - df["Target_Dose_mg_kg"]) / df["Target_Dose_mg_kg"]
405 |     ).abs().mul(100).round(2)
406 | 
407 |     # Map each row's cohort to its rule parameters (vectorized via map)
408 |     df["_param_name"] = df["Cohort"].map(COHORT_RULE_MAP).fillna(fallback_rule["Assay_Parameter"])
409 | 
410 |     minor_map = {r["Assay_Parameter"]: r["Minor_Variance_Limit_Percent"] for r in rules_json["rules"]}
411 |     major_map = {r["Assay_Parameter"]: r["Major_Variance_Limit_Percent"] for r in rules_json["rules"]}
412 |     action_map = {r["Assay_Parameter"]: r["Action_Required"] for r in rules_json["rules"]}
413 | 
414 |     df["_minor"] = df["_param_name"].map(minor_map)
415 |     df["_major"] = df["_param_name"].map(major_map)
416 | 
417 |     # Vectorized status assignment using numpy.select
418 |     conditions = [
419 |         df["Deviation_Pct"] <= df["_minor"],
420 |         df["Deviation_Pct"] <= df["_major"],
421 |     ]
422 |     df["Status"] = np.select(
423 |         conditions,
424 |         ["INCLUDE", "REVIEW"],
425 |         default="EXCLUDE",
426 |     )
427 |     df["System_Action"] = np.select(
428 |         conditions,
429 |         ["Approved – within acceptable range", df["_param_name"].map(action_map)],
430 |         default="Exclude – exceeds major variance limit",
431 |     )
432 |     df["Applied_Rule"] = df["_param_name"]
433 | 
434 |     # Drop temp columns
435 |     df.drop(columns=["_param_name", "_minor", "_major"], inplace=True)
436 | 
437 |     # Stamp each record
438 |     df["Record_ID"] = [new_record_id(project_id) for _ in range(len(df))]
439 |     df["Import_TS"] = now_ts()
440 | 
441 |     return df
442 | 
