444 | def compute_delta(new_df: pd.DataFrame, prev_df: pd.DataFrame) -> pd.DataFrame:
445 |     """Tag rows that are new vs previously seen (by Animal_ID)."""
446 |     if prev_df is None or prev_df.empty:
447 |         new_df = new_df.copy()
448 |         new_df["Delta"] = "NEW"
449 |         return new_df
450 |     prev_ids = set(prev_df["Animal_ID"].astype(str))
451 |     new_df = new_df.copy()
452 |     new_df["Delta"] = new_df["Animal_ID"].astype(str).apply(
453 |         lambda x: "NEW" if x not in prev_ids else "EXISTING"
454 |     )
455 |     return new_df
