458 | def _df_hash(df: pd.DataFrame) -> str:
459 |     """Stable hash of DataFrame content for use as a cache key."""
460 |     return hashlib.md5(pd.util.hash_pandas_object(df, index=True).values.tobytes()).hexdigest()
