491 |             f"A compliance review of {summary.get('total', 0):,} pre-clinical dosing records was completed. "
492 |             f"{summary.get('include_count', 0):,} records ({summary.get('include_pct', 0):.1f}%) met all acceptance criteria and are cleared for inclusion in the eCTD submission. "
493 |             f"{summary.get('review_count', 0):,} records ({summary.get('review_pct', 0):.1f}%) require scientific review prior to inclusion. "
