    n_new   = int((results_df["Delta"] == "NEW").sum()) if "Delta" in results_df.columns else total

    pct_inc = n_inc / total * 100
    pct_rev = n_rev / total * 100
    pct_exc = n_exc / total * 100

    max_dev = results_df["Deviation_Pct"].max()
