        "INCLUDE": "✓ INCLUDE",
        "REVIEW":  "⚠ REVIEW_REQUIRED",
        "EXCLUDE": "✕ EXCLUDE_EXCEPTIONAL",
    }
    label = labels.get(status, status)
    return f'<span class="badge {cls}"><span class="dot {dot_cls}"></span>{label}</span>'


