    "Postcode (UK)":re.compile(r"\b[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}\b"),
    "IP Address":   re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b"),
